arguments.content:
variable "resource_prefix" {
  type = string
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "aws_endpoint_url" {
  type    = string
  default = "http://aws:4566"
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "api_image" {
  type = string
}

variable "projector_image" {
  type = string
}

variable "relay_image" {
  type = string
}

variable "archiver_image" {
  type = string
}

variable "api_image_id" {
  type    = string
  default = ""
}

variable "projector_image_id" {
  type    = string
  default = ""
}

variable "relay_image_id" {
  type    = string
  default = ""
}

variable "archiver_image_id" {
  type    = string
  default = ""
}

variable "vpc_cidr" {
  type    = string
  default = "10.42.0.0/16"
}

locals {
  prefix = var.resource_prefix

  common_tags = {
    ClearLedgerDeployment = var.resource_prefix
  }

  azs = ["${var.region}a", "${var.region}b"]

  account_id = data.aws_caller_identity.current.account_id

  log_group_names = {
    api       = "/clearledger/${var.resource_prefix}/api"
    projector = "/clearledger/${var.resource_prefix}/projector"
    relay     = "/clearledger/${var.resource_prefix}/outbox-relay"
    archiver  = "/clearledger/${var.resource_prefix}/audit-archiver"
  }
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.prefix}-public-${local.azs[count.index]}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.prefix}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Rules are declared inline so that every apply converges the
# full rule set (out-of-band rules are revoked on re-apply).
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB: HTTP in from internet, 8080 out to ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-alb"
  }
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks: 8080 from ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API traffic from the ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane, PostgreSQL and Valkey"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.prefix}-ecs"
  }
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL: 5432 from ECS tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "PostgreSQL from in-VPC workers"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress = []

  tags = {
    Name = "${local.prefix}-rds"
  }
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey: 6379 from ECS tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "Valkey from in-VPC workers"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress = []

  tags = {
    Name = "${local.prefix}-valkey"
  }
}

locals {
  kms_usages = ["database", "messaging", "projection", "audit"]
}

resource "aws_kms_key" "this" {
  for_each = toset(local.kms_usages)

  description             = "ClearLedger ${local.prefix} ${each.key} key"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = {
    Name               = "${local.prefix}-${each.key}"
    ClearLedgerKeyUsage = each.key
  }
}

resource "aws_kms_alias" "this" {
  for_each = toset(local.kms_usages)

  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = local.log_group_names

  name              = each.value
  retention_in_days = 14

  tags = {
    Name = "${local.prefix}-${each.key}-logs"
  }
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL 16
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.prefix}-db-subnets"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.prefix}-db-subnets"
  }
}

resource "aws_db_instance" "main" {
  identifier             = "${local.prefix}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  apply_immediately      = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = {
    Name = "${local.prefix}-postgres"
  }

  lifecycle {
    # The emulator allocates the listener port; never replace the instance
    # (and its committed ledger data) because of cosmetic read-back drift.
    ignore_changes = [port, engine_version, allocated_storage, storage_type]
  }
}

# ---------------------------------------------------------------------------
# DynamoDB projection table
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }

  attribute {
    name = "SK"
    type = "S"
  }

  attribute {
    name = "GSI1PK"
    type = "S"
  }

  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = {
    Name = "${local.prefix}-projections"
  }
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey 8
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.prefix}-cache-subnets"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.prefix}-cache-subnets"
  }
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id       = "${local.prefix}-valkey"
  description                = "ClearLedger ${local.prefix} projection cache"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.main.name
  security_group_ids         = [aws_security_group.valkey.id]
  automatic_failover_enabled = false
  multi_az_enabled           = false
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false
  apply_immediately          = true

  tags = {
    Name = "${local.prefix}-valkey"
  }

  lifecycle {
    # The emulator may substitute the listener port when 6379 is taken.
    ignore_changes = [port, engine_version, parameter_group_name]
  }
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-audit-archive"
  force_destroy = true

  tags = {
    Name = "${local.prefix}-audit-archive"
  }
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = false
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS main queue + DLQ
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600

  tags = {
    Name = "${local.prefix}-events-dlq"
  }
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = {
    Name = "${local.prefix}-events"
  }
}

resource "aws_cognito_user_pool" "main" {
  name = "${local.prefix}-users"

  tags = {
    Name = "${local.prefix}-users"
  }
}

resource "aws_cognito_resource_server" "clearledger" {
  identifier   = "clearledger"
  name         = "${local.prefix}-clearledger-api"
  user_pool_id = aws_cognito_user_pool.main.id

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }

  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }

  scope {
    scope_name        = "admin"
    scope_description = "Rebuild settlement projections"
  }
}

locals {
  cognito_clients = {
    read  = "clearledger/read"
    write = "clearledger/write"
    admin = "clearledger/admin"
  }
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = local.cognito_clients

  name                                 = "${local.prefix}-${each.key}"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = [each.value]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]

  depends_on = [aws_cognito_resource_server.clearledger]
}

locals {
  auth_issuer   = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}"
  auth_jwks_url = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"
  auth_audiences = join(",", [
    aws_cognito_user_pool_client.this["read"].id,
    aws_cognito_user_pool_client.this["write"].id,
    aws_cognito_user_pool_client.this["admin"].id,
  ])
  token_endpoint = "${var.aws_endpoint_url}/cognito-idp/oauth2/token"
}

locals {
  database_url = "postgres://${var.db_username}:${var.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
  valkey_host  = aws_elasticache_replication_group.valkey.primary_endpoint_address
  valkey_port  = aws_elasticache_replication_group.valkey.port
  valkey_url   = "redis://${local.valkey_host}:${local.valkey_port}"

  aws_runtime_env = {
    AWS_REGION            = var.region
    AWS_DEFAULT_REGION    = var.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = var.aws_endpoint_url
  }

  api_env = merge(local.aws_runtime_env, {
    PORT                 = "8080"
    DATABASE_URL         = local.database_url
    SQS_QUEUE_URL        = aws_sqs_queue.main.url
    PROJECTION_TABLE     = aws_dynamodb_table.projections.name
    VALKEY_URL           = local.valkey_url
    CACHE_TTL_SECONDS    = "90"
    AUTH_ISSUER          = local.auth_issuer
    AUTH_AUDIENCES       = local.auth_audiences
    AUTH_JWKS_URL        = local.auth_jwks_url
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["api"].name
  })
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------
resource "aws_lb" "api" {
  name               = "${local.prefix}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]

  tags = {
    Name = "${local.prefix}-alb"
  }
}

resource "aws_lb_target_group" "api" {
  name        = "${local.prefix}-api-tg"
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 5

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = {
    Name = "${local.prefix}-api-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.api.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = {
    Name = "${local.prefix}-http"
  }
}

# ---------------------------------------------------------------------------
# ECS Fargate API service
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "${local.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name = "${local.prefix}-cluster"
  }
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.prefix}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "api"
      image     = var.api_image
      essential = true
      portMappings = [
        {
          containerPort = 8080
          hostPort      = 8080
          protocol      = "tcp"
        }
      ]
      environment = [
        for k in sort(keys(local.api_env)) : { name = k, value = local.api_env[k] }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.this["api"].name
          awslogs-region        = var.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])

  tags = {
    Name = "${local.prefix}-api"
  }
}

resource "aws_ecs_service" "api" {
  name            = "${local.prefix}-api"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.api.arn
  launch_type     = "FARGATE"
  desired_count   = 2

  deployment_minimum_healthy_percent = 50
  deployment_maximum_percent         = 200

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  wait_for_steady_state = false

  tags = {
    Name = "${local.prefix}-api"
  }

  depends_on = [aws_lb_listener.http]
}

# ---------------------------------------------------------------------------
# Lambda container workers
# ---------------------------------------------------------------------------
resource "aws_lambda_function" "projector" {
  function_name = "${local.prefix}-projector"
  package_type  = "Image"
  image_uri     = var.projector_image
  role          = aws_iam_role.projector.arn
  timeout       = 30
  memory_size   = 256

  environment {
    variables = merge(local.aws_runtime_env, {
      PROJECTION_TABLE     = aws_dynamodb_table.projections.name
      VALKEY_URL           = local.valkey_url
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["projector"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["projector"].name
  }

  tags = {
    Name = "${local.prefix}-projector"
  }
}

resource "aws_lambda_function" "relay" {
  function_name = "${local.prefix}-outbox-relay"
  package_type  = "Image"
  image_uri     = var.relay_image
  role          = aws_iam_role.relay.arn
  timeout       = 60
  memory_size   = 256

  environment {
    variables = merge(local.aws_runtime_env, {
      DATABASE_URL         = local.database_url
      SQS_QUEUE_URL        = aws_sqs_queue.main.url
      OUTBOX_BATCH_SIZE    = "50"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["relay"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["relay"].name
  }

  tags = {
    Name = "${local.prefix}-outbox-relay"
  }
}

resource "aws_lambda_function" "archiver" {
  function_name = "${local.prefix}-audit-archiver"
  package_type  = "Image"
  image_uri     = var.archiver_image
  role          = aws_iam_role.archiver.arn
  timeout       = 120
  memory_size   = 256

  environment {
    variables = merge(local.aws_runtime_env, {
      DATABASE_URL         = local.database_url
      AUDIT_BUCKET         = aws_s3_bucket.audit.bucket
      AUDIT_PREFIX         = "ledger-audit/"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["archiver"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["archiver"].name
  }

  tags = {
    Name = "${local.prefix}-audit-archiver"
  }
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]

  tags = {
    Name = "${local.prefix}-projector-esm"
  }
}

# ---------------------------------------------------------------------------
# EventBridge Scheduler
# ---------------------------------------------------------------------------
resource "aws_scheduler_schedule" "outbox" {
  name                         = "${local.prefix}-outbox-relay"
  group_name                   = "default"
  state                        = "ENABLED"
  schedule_expression          = "rate(1 minute)"
  schedule_expression_timezone = "UTC"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.scheduler.arn
    input    = jsonencode({ source = "clearledger.scheduler", job = "outbox-relay" })

    retry_policy {
      maximum_event_age_in_seconds = 300
      maximum_retry_attempts       = 2
    }
  }
}

resource "aws_scheduler_schedule" "archive" {
  name                         = "${local.prefix}-audit-archiver"
  group_name                   = "default"
  state                        = "ENABLED"
  schedule_expression          = "rate(5 minutes)"
  schedule_expression_timezone = "UTC"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.archiver.arn
    role_arn = aws_iam_role.scheduler.arn
    input    = jsonencode({ source = "clearledger.scheduler", job = "audit-archiver" })

    retry_policy {
      maximum_event_age_in_seconds = 600
      maximum_retry_attempts       = 2
    }
  }
}

locals {
  kms_arn = { for k, v in aws_kms_key.this : k => v.arn }
  all_kms = [for k in local.kms_usages : aws_kms_key.this[k].arn]

  # Per-workload log group ARN patterns ("...:log-group:/clearledger/<prefix>/<workload>*")
  lg = { for k, v in aws_cloudwatch_log_group.this : k => "${v.arn}*" }

  queue_arn  = aws_sqs_queue.main.arn
  dlq_arn    = aws_sqs_queue.dlq.arn
  table_arn  = aws_dynamodb_table.projections.arn
  gsi_arn    = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn = aws_s3_bucket.audit.arn

  log_write_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  log_deny_actions  = ["logs:CreateLogStream", "logs:PutLogEvents"]
  kms_use_actions   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny_actions  = ["kms:Decrypt", "kms:GenerateDataKey"]
  sqs_core_actions  = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_core_actions  = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_core_actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]

  # Guardrail shared by every role.
  deny_key_destruction = {
    Sid      = "DenyKmsKeyDestruction"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_kms
  }

  deny_s3_all = {
    Sid      = "DenyAuditBucketAccess"
    Effect   = "Deny"
    Action   = local.s3_core_actions
    Resource = [local.bucket_arn, "${local.bucket_arn}/*"]
  }

  deny_ddb_all = {
    Sid      = "DenyProjectionTableAccess"
    Effect   = "Deny"
    Action   = local.ddb_core_actions
    Resource = [local.table_arn, local.gsi_arn]
  }

  deny_sqs_all = {
    Sid      = "DenyQueueAccess"
    Effect   = "Deny"
    Action   = local.sqs_core_actions
    Resource = [local.queue_arn, local.dlq_arn]
  }

  role_names = {
    ecs_execution = "${local.prefix}-ecs-execution"
    ecs_task      = "${local.prefix}-ecs-task"
    projector     = "${local.prefix}-projector"
    relay         = "${local.prefix}-outbox-relay"
    archiver      = "${local.prefix}-audit-archiver"
    scheduler     = "${local.prefix}-scheduler"
  }
}

data "aws_iam_policy_document" "trust_ecs" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "trust_lambda" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "trust_scheduler" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["scheduler.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# 1. ECS execution role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution" {
  name               = local.role_names.ecs_execution
  assume_role_policy = data.aws_iam_policy_document.trust_ecs.json
  tags               = { ClearLedgerRole = "ecs_execution" }
}

resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.prefix}-ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ApiLogStreams"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = [local.lg.api]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyAllWorkloadKeys"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = local.all_kms
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = [local.lg.projector, local.lg.relay, local.lg.archiver]
      },
      local.deny_key_destruction,
    ]
  })
}

# ---------------------------------------------------------------------------
# 2. ECS task role (API)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task" {
  name               = local.role_names.ecs_task
  assume_role_policy = data.aws_iam_policy_document.trust_ecs.json
  tags               = { ClearLedgerRole = "ecs_task" }
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.prefix}-ecs-task-policy"
  role = aws_iam_role.ecs_task.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishDomainEvents"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn.messaging, local.kms_arn.projection]
      },
      {
        Sid      = "ApiLogStreams"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = [local.lg.api]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDeadLetterQueue"
        Effect   = "Deny"
        Action   = local.sqs_core_actions
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      local.deny_s3_all,
      {
        Sid      = "DenyDatabaseAndAuditKeys"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = [local.kms_arn.database, local.kms_arn.audit]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = [local.lg.projector, local.lg.relay, local.lg.archiver]
      },
      local.deny_key_destruction,
    ]
  })
}

# ---------------------------------------------------------------------------
# 3. Projector Lambda role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "projector" {
  name               = local.role_names.projector
  assume_role_policy = data.aws_iam_policy_document.trust_lambda.json
  tags               = { ClearLedgerRole = "projector" }
}

resource "aws_iam_role_policy" "projector" {
  name = "${local.prefix}-projector-policy"
  role = aws_iam_role.projector.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ConsumeDomainEvents"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ForwardToDeadLetterQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "UpsertProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn.messaging, local.kms_arn.projection]
      },
      {
        Sid      = "ProjectorLogStreams"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = [local.lg.projector]
      },
      {
        Sid      = "DenyPublishMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyConsumeDeadLetterQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionDeletion"
        Effect   = "Deny"
        Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      local.deny_s3_all,
      {
        Sid      = "DenyDatabaseAndAuditKeys"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = [local.kms_arn.database, local.kms_arn.audit]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = [local.lg.api, local.lg.relay, local.lg.archiver]
      },
      local.deny_key_destruction,
    ]
  })
}

# ---------------------------------------------------------------------------
# 4. Outbox relay Lambda role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "relay" {
  name               = local.role_names.relay
  assume_role_policy = data.aws_iam_policy_document.trust_lambda.json
  tags               = { ClearLedgerRole = "relay" }
}

resource "aws_iam_role_policy" "relay" {
  name = "${local.prefix}-outbox-relay-policy"
  role = aws_iam_role.relay.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishDomainEvents"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "UseMessagingAndDatabaseKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn.messaging, local.kms_arn.database]
      },
      {
        Sid      = "RelayLogStreams"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = [local.lg.relay]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDeadLetterQueue"
        Effect   = "Deny"
        Action   = local.sqs_core_actions
        Resource = [local.dlq_arn]
      },
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyProjectionAndAuditKeys"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = [local.kms_arn.projection, local.kms_arn.audit]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = [local.lg.api, local.lg.projector, local.lg.archiver]
      },
      local.deny_key_destruction,
    ]
  })
}

# ---------------------------------------------------------------------------
# 5. Audit archiver Lambda role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "archiver" {
  name               = local.role_names.archiver
  assume_role_policy = data.aws_iam_policy_document.trust_lambda.json
  tags               = { ClearLedgerRole = "archiver" }
}

resource "aws_iam_role_policy" "archiver" {
  name = "${local.prefix}-audit-archiver-policy"
  role = aws_iam_role.archiver.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AppendAuditObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource = ["${local.bucket_arn}/ledger-audit/*"]
      },
      {
        Sid      = "AuditBucketMetadata"
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [local.bucket_arn]
      },
      {
        Sid      = "UseAuditAndDatabaseKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn.audit, local.kms_arn.database]
      },
      {
        Sid      = "ArchiverLogStreams"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = [local.lg.archiver]
      },
      {
        Sid      = "DenyAuditDeletion"
        Effect   = "Deny"
        Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
        Resource = [local.bucket_arn, "${local.bucket_arn}/*"]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      {
        Sid      = "DenyMessagingAndProjectionKeys"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = [local.kms_arn.messaging, local.kms_arn.projection]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = [local.lg.api, local.lg.projector, local.lg.relay]
      },
      local.deny_key_destruction,
    ]
  })
}

# ---------------------------------------------------------------------------
# 6. EventBridge Scheduler role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "scheduler" {
  name               = local.role_names.scheduler
  assume_role_policy = data.aws_iam_policy_document.trust_scheduler.json
  tags               = { ClearLedgerRole = "scheduler" }
}

resource "aws_iam_role_policy" "scheduler" {
  name = "${local.prefix}-scheduler-policy"
  role = aws_iam_role.scheduler.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InvokeScheduledWorkers"
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = [aws_lambda_function.relay.arn, aws_lambda_function.archiver.arn]
      },
      {
        Sid      = "DenyInvokeProjector"
        Effect   = "Deny"
        Action   = ["lambda:InvokeFunction"]
        Resource = [aws_lambda_function.projector.arn]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyAllWorkloadKeys"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = local.all_kms
      },
      {
        Sid      = "DenyAllLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = [local.lg.api, local.lg.projector, local.lg.relay, local.lg.archiver]
      },
      local.deny_key_destruction,
    ]
  })
}

# ---------------------------------------------------------------------------
# Exclusive ownership: any out-of-band inline policy or managed policy
# attachment on the six workload roles is removed on every apply.
# ---------------------------------------------------------------------------
locals {
  workload_roles = {
    ecs_execution = { role = aws_iam_role.ecs_execution.name, policy = aws_iam_role_policy.ecs_execution.name }
    ecs_task      = { role = aws_iam_role.ecs_task.name, policy = aws_iam_role_policy.ecs_task.name }
    projector     = { role = aws_iam_role.projector.name, policy = aws_iam_role_policy.projector.name }
    relay         = { role = aws_iam_role.relay.name, policy = aws_iam_role_policy.relay.name }
    archiver      = { role = aws_iam_role.archiver.name, policy = aws_iam_role_policy.archiver.name }
    scheduler     = { role = aws_iam_role.scheduler.name, policy = aws_iam_role_policy.scheduler.name }
  }
}

resource "aws_iam_role_policies_exclusive" "this" {
  for_each     = local.workload_roles
  role_name    = each.value.role
  policy_names = [each.value.policy]
}

resource "aws_iam_role_policy_attachments_exclusive" "this" {
  for_each    = local.workload_roles
  role_name   = each.value.role
  policy_arns = []
}

output "manifest" {
  description = "Submission manifest (matches contracts/schemas/manifest.schema.json)"
  sensitive   = true
  value = {
    resource_prefix = local.prefix
    region          = var.region
    service_url     = "http://${aws_lb.api.dns_name}"

    network = {
      vpc_id             = aws_vpc.main.id
      public_subnet_ids  = aws_subnet.public[*].id
      private_subnet_ids = aws_subnet.private[*].id
      security_group_ids = {
        alb    = aws_security_group.alb.id
        ecs    = aws_security_group.ecs.id
        rds    = aws_security_group.rds.id
        valkey = aws_security_group.valkey.id
      }
    }

    ingress = {
      alb_arn          = aws_lb.api.arn
      alb_dns_name     = aws_lb.api.dns_name
      listener_arn     = aws_lb_listener.http.arn
      target_group_arn = aws_lb_target_group.api.arn
      container_port   = 8080
    }

    compute = {
      cluster_arn         = aws_ecs_cluster.main.arn
      cluster_name        = aws_ecs_cluster.main.name
      service_arn         = aws_ecs_service.api.id
      service_name        = aws_ecs_service.api.name
      task_definition_arn = aws_ecs_task_definition.api.arn
      desired_count       = aws_ecs_service.api.desired_count
    }

    database = {
      instance_id  = aws_db_instance.main.identifier
      instance_arn = aws_db_instance.main.arn
      endpoint     = aws_db_instance.main.address
      port         = aws_db_instance.main.port
      db_name      = var.db_name
      username     = var.db_username
    }

    messaging = {
      queue_name                = aws_sqs_queue.main.name
      queue_url                 = aws_sqs_queue.main.url
      queue_arn                 = aws_sqs_queue.main.arn
      dlq_name                  = aws_sqs_queue.dlq.name
      dlq_url                   = aws_sqs_queue.dlq.url
      dlq_arn                   = aws_sqs_queue.dlq.arn
      event_source_mapping_uuid = aws_lambda_event_source_mapping.projector.uuid
      max_receive_count         = 4
    }

    workers = {
      projector = {
        function_name = aws_lambda_function.projector.function_name
        function_arn  = aws_lambda_function.projector.arn
      }
      outbox_relay = {
        function_name = aws_lambda_function.relay.function_name
        function_arn  = aws_lambda_function.relay.arn
      }
      audit_archiver = {
        function_name = aws_lambda_function.archiver.function_name
        function_arn  = aws_lambda_function.archiver.arn
      }
    }

    projections = {
      table_name = aws_dynamodb_table.projections.name
      table_arn  = aws_dynamodb_table.projections.arn
      gsi_name   = "AccountIndex"
    }

    cache = {
      cluster_id = aws_elasticache_replication_group.valkey.id
      engine     = "valkey"
      endpoint   = local.valkey_host
      port       = local.valkey_port
    }

    audit = {
      bucket_name = aws_s3_bucket.audit.bucket
      bucket_arn  = aws_s3_bucket.audit.arn
      prefix      = "ledger-audit/"
    }

    schedules = {
      outbox_schedule_name  = aws_scheduler_schedule.outbox.name
      outbox_schedule_arn   = aws_scheduler_schedule.outbox.arn
      archive_schedule_name = aws_scheduler_schedule.archive.name
      archive_schedule_arn  = aws_scheduler_schedule.archive.arn
    }

    auth = {
      user_pool_id               = aws_cognito_user_pool.main.id
